const courses=[],q=(question,options,correct,explanation)=>({question,options,correct,explanation});
function add(d){d.verifiedDate=verifiedDate;d.time=['60–90 分钟 + 项目练习','60–90 min + project practice'];courses.push(d);}
add({id:'m12-measure',track:'mechanical',title:['先量清楚：尺寸、单位与测量记录','Measure first: dimensions, units and records'],pre:[],bench:'geometry',goal:['把一件实物变成有单位、基准和不确定性的尺寸记录。','Turn an object into a dimension record with units, datums and uncertainty.'],terms:[['基准','Datum','所有位置共同参照的面、线或点。','A shared reference face, line or point.'],['分辨率','Resolution','仪表能显示的最小增量，不等于准确度。','The smallest displayed increment, not accuracy.']],sections:[
['从一个支架任务开始','Start with a bracket task','先拿纸画出传感器、底板和安装孔。今天只测断电的小零件，不拆带电设备。标明哪个面贴底板、哪两个孔负责固定；不需要会画漂亮透视图，先让另一人认出测的是哪里。','Sketch a sensor, base and mounting holes. Measure small unpowered parts. Mark the face touching the base and the two mounting holes. A readable reference sketch matters more than attractive perspective.'],
['选单位，找基准','Choose units and a datum','本路线使用mm，1 cm=10 mm。把底板左下角作为位置基准，宽、长、厚是尺寸，孔中心到边是位置。不要把孔边距离误当孔中心距离；同一张表写清外径、内径和深度。','Use millimetres throughout: 1 cm=10 mm. Choose the lower-left corner as the location datum. Width, length and thickness describe size; centre-to-edge distances locate holes. Distinguish a hole edge from its centre and record external, internal and depth measurements separately.'],
['卡尺先归零再接触','Zero and align the caliper','擦净测量面，闭合检查零位，选择外测爪、内测爪或深度杆。让测量方向对准要量的尺寸，用稳定轻力接触，不把软塑料夹变形。测孔径时轻微摆正寻找正确跨径，不能斜着读一个较长距离。','Clean the measuring faces and check zero. Select outside jaws, inside jaws or depth rod. Align with the desired dimension and use consistent light force without deforming plastic. Align inside jaws across the diameter rather than reading a diagonal.'],
['读数要能复查','Make readings repeatable','同一尺寸松开重测三次，记录20.08、20.10、20.09 mm，而不是只写20。均值20.09 mm，极差0.02 mm只反映这次重复性；仪表误差、温度和接触方式仍可能偏移全部读数。屏幕显示0.01 mm不证明准确到0.01 mm。','Release and repeat a measurement three times, for example 20.08, 20.10 and 20.09 mm. Mean 20.09 mm and range 0.02 mm describe this repeatability only. Instrument error, temperature and contact can shift all readings; a 0.01 mm display does not establish that accuracy.'],
['把测量变成建模输入','Convert measurements into model inputs','建立尺寸表：对象、测点、单位、三次读数、采用值、待确认项。在操作台改长宽厚，核对体积随厚度成正比。Fusion用Inspect > Measure核对模型；SOLIDWORKS用Evaluate > Measure。软件测的是理想几何，不是实物误差。','Create columns for object, measurement location, units, readings, chosen value and uncertainty. Change plate dimensions in the bench and verify volume scales with thickness. Use Inspect > Measure in Fusion or Evaluate > Measure in SOLIDWORKS; these measure ideal geometry, not physical error.']
],example:['40×30×3 mm板体积3600 mm³=3.6 cm³；两个直径4 mm通孔移除2π×2²×3≈75.40 mm³，净体积3524.60 mm³。','A 40×30×3 mm plate has 3600 mm³=3.6 cm³ volume. Two 4 mm through-holes remove 75.40 mm³, leaving 3524.60 mm³.'],exercise:['记录一块无源小板的长宽厚与两孔位置，每个尺寸重测三次；在操作台复现外形。','Measure an unpowered plate and two hole positions three times, then reproduce the overall dimensions in the bench.'],acceptance:['另一人能按你的基准定位孔；单位一致；能解释分辨率、重复性与准确度的区别。','Another person can locate the holes from your datum; units agree; explain resolution, repeatability and accuracy.'],refs:['measure'],quiz:[q(['显示0.01 mm代表什么？','What does a 0.01 mm display indicate?'],[['显示分辨率','Display resolution'],['绝对误差为零','Zero absolute error'],['实物完全准确','Perfect physical accuracy']],0,['显示增量不能代替仪表误差规格和测量方法。','Display increments do not replace error specifications and measurement technique.']),q(['3.6 cm³等于？','3.6 cm³ equals?'],[['36 mm³','36 mm³'],['3600 mm³','3600 mm³'],['360 mm³','360 mm³']],1,['1 cm³=(10 mm)³=1000 mm³。','1 cm³=(10 mm)³=1000 mm³.'])]});
add({id:'m12-sketch',track:'mechanical',title:['第一次草图：平面、轮廓与基准','First sketch: planes, profiles and datums'],pre:['m12-measure'],bench:'geometry',goal:['从空白文件画出可以修改的中心对称安装板草图。','Create an editable centred mounting-plate sketch from a blank design.'],terms:[['轮廓','Profile','构成待拉伸区域的边界。','Boundary of the region to be extruded.'],['构造线','Construction line','用于定位，不构成实体轮廓的辅助线。','A reference line excluded from a solid profile.']],sections:[
['先保存，再选择平面','Save, then choose a plane','新建设计，以sensor_mount_v01命名并确认文档单位为mm。观察XY、XZ、YZ平面，把底板放在XY平面；正视草图能减少透视误判。Fusion创建草图后选平面；SW新建零件后选上视基准面并进入草图。','Create sensor_mount_v01 and confirm millimetres. Put the base on the XY/top plane and look normal to it. In Fusion create a sketch and choose the plane; in SOLIDWORKS select the Top plane of a new part and start Sketch.'],
['矩形不靠手感画准','Sketch the shape before sizing it','以原点画中心矩形，大致40×30即可；随后用尺寸规定准确大小。先画拓扑再加尺寸能让你知道尺寸控制哪条边。放大视图不改变真实毫米数，屏幕上看着更大不是零件变大。','Draw a centre rectangle at the origin, approximately 40×30, then dimension it. Creating topology before precise size clarifies which edge each dimension controls. Zoom changes the view, not millimetres or the physical part.'],
['闭合与相交要分清','Distinguish closure from intersection','普通实心拉伸需要有效闭合区域。放大四角检查端点是否重合；线看似碰在一起但留有小缝，可能无法选择内部区域。多画一条跨过矩形的实线会把区域切开，辅助中心线应设为构造几何。','A normal solid extrusion needs a valid closed region. Inspect corner endpoints: a tiny gap can prevent selecting the interior. An extra ordinary line across the rectangle can divide it, while a centre reference should use construction geometry.'],
['孔先定位中心再给直径','Locate centres before diameters','画一条水平构造线，放两个圆，先让圆心在该线上，再规定孔中心距。直径和位置是两种约束；只标直径，圆仍可能移动。安装板对称时用原点做共同参照，改长度后孔不会无意跑向一边。','Draw a horizontal construction line and two circles on it, then constrain their centre spacing. Diameter and position are separate: a sized circle may still move. Using the origin as a common reference preserves symmetry when length changes.'],
['用拖动暴露缺失关系','Drag to reveal missing constraints','结束前轻拖边和孔心，看哪些自由度仍在。Fusion用Sketch Dimension与Constraints，SW用Smart Dimension与Add Relations。不要直接Fix所有线掩盖缺失设计关系；保存草图截图，圈出原点、尺寸和构造线。','Gently drag edges and centres to reveal remaining freedom. Use Sketch Dimension and Constraints in Fusion, or Smart Dimension and Add Relations in SOLIDWORKS. Fixing everything hides design intent; save a sketch view marking the origin, dimensions and construction line.']
],example:['板40×30 mm，孔中心距24 mm且关于原点对称，孔心为(−12,0)与(12,0)。各孔距短边8 mm，直径4 mm时边缘余量6 mm。','For a 40×30 mm plate and symmetric 24 mm hole spacing, centres are (−12,0) and (12,0). Each is 8 mm from its nearest short edge; a 4 mm hole leaves 6 mm material.'],exercise:['建矩形和两孔；只将板长改成50 mm，观察孔中心距是否仍保持24 mm。','Create the rectangle and holes; change plate length to 50 mm and verify 24 mm centre spacing remains.'],acceptance:['有可选闭合区域；辅助线不切开轮廓；能指出每个尺寸控制的几何。','The region is selectable, reference lines do not divide it, and every dimension has an identified purpose.'],refs:['sketch','swsketch'],quiz:[q(['放大视图会改变零件尺寸吗？','Does zoom change part dimensions?'],[['会','Yes'],['不会','No'],['只改变孔径','Only hole diameter']],1,['缩放相机不会修改草图尺寸。','Camera zoom does not edit sketch dimensions.']),q(['两个孔距24 mm且中心对称，圆心X坐标？','Symmetric holes 24 mm apart have X coordinates?'],[['±24 mm','±24 mm'],['0与24 mm','0 and 24 mm'],['±12 mm','±12 mm']],2,['从中心各分一半。','Split the spacing equally about the origin.'])]});
add({id:'m12-parameters',track:'mechanical',title:['参数与约束：改一处，结构仍成立','Parameters and constraints: preserve design intent'],pre:['m12-sketch'],bench:'geometry',goal:['用有单位的参数建立一族支架，并识别欠约束和过约束。','Build a bracket family using unit-aware parameters and recognize under/overconstraint.'],terms:[['自由度','Degree of freedom','还能独立改变的位置或形状变量。','An independently changeable position or shape variable.'],['表达式','Expression','由数值、单位和其他参数计算的关系。','A relationship calculated from values, units and parameters.']],sections:[
['先用语言表达设计意图','State the intended relationship','“两孔始终关于中心对称”“边缘至少留材料”是设计意图；“当前看着对称”只是一个位置。先写出哪些尺寸固定、哪些跟着变，才决定用对称、相等、重合还是尺寸关系。','“Holes remain symmetric” and “material remains at edges” describe design intent; “looks centred now” describes only one state. Decide what stays fixed and what follows before choosing symmetry, equality, coincidence or dimensions.'],
['建立四个有意义的参数','Name four useful parameters','Fusion在Modify > Change Parameters中设length=40 mm、width=30 mm、thickness=3 mm、edge=8 mm。让孔中心距pitch=length−2×edge，尺寸框引用参数名。SW对应Tools > Equations中的Global Variables和尺寸方程。','In Fusion Change Parameters, define length=40 mm, width=30 mm, thickness=3 mm and edge=8 mm. Set pitch=length−2×edge and reference names in dimensions. SOLIDWORKS uses global variables and dimension equations in Tools > Equations.'],
['不要重复表达同一关系','Avoid redundant relationships','如果已经有对称和中心距，就不要再把两孔到中心的距离各写成固定值；参数一改可能冲突。过约束时先看新加的关系，暂时撤销一项并观察，而不是把整个草图删掉。','With symmetry and centre spacing already defined, adding independent fixed distances from each hole to the origin can conflict when parameters change. Inspect the newest relation and remove one redundant requirement before rebuilding the entire sketch.'],
['用三组尺寸验证参数','Test three configurations','测试length=40、50、60 mm，edge仍8 mm，pitch应为24、34、44 mm。若孔仍停在旧位置，检查引用的是数值还是表达式。留意最小板长：当孔径增大时，孔可能碰边，软件算得出不代表结构可制造。','Test lengths 40, 50 and 60 mm with edge=8 mm; pitch should become 24, 34 and 44 mm. If holes stay put, inspect literal dimensions versus expressions. Also test the smallest size: a solvable model can still place holes too close to an edge.'],
['记录为何选择这个尺寸','Record why a dimension exists','给参数写注释：板宽来自传感器外形，孔距来自安装接口，厚度先作为原型假设。别把未验证厚度写成承载保证。保存尺寸变更记录，后续打印偏差用新参数修正，不要偷偷缩放全部模型。','Comment parameters with their source: sensor envelope, mounting interface or prototype assumption. An untested thickness is not a load rating. Record changes and correct print fit through explicit parameters instead of silently scaling the whole model.']
],example:['length从40改60，edge固定8，pitch=60−16=44 mm；若孔径4 mm，边缘最薄仍8−2=6 mm。','At length 60 and edge 8, pitch=44 mm. With 4 mm holes, the nearest edge ligament remains 8−2=6 mm.'],exercise:['建立三尺寸族，另故意添加一个冲突尺寸，识别并恢复原有关系。','Create three sizes, intentionally add a conflicting dimension, then identify and remove the conflict.'],acceptance:['三组尺寸都能重建；能解释一个参数的来源和一个冲突关系。','All sizes rebuild; explain the source of one parameter and the cause of one conflicting relation.'],refs:['parameter','swsketch'],quiz:[q(['length=50，edge=8，pitch是多少？','length=50, edge=8: pitch?'],[['34 mm','34 mm'],['42 mm','42 mm'],['66 mm','66 mm']],0,['两端各减8 mm。','Subtract 8 mm at both ends.']),q(['过约束首先应检查？','First inspect when overconstrained?'],[['电脑内存','Computer RAM'],['重复或冲突关系','Redundant or conflicting relations'],['显示器尺寸','Monitor size']],1,['几何关系互相冲突，重装软件不能修复设计逻辑。','Conflicting geometry relationships require a design correction.'])]});
add({id:'m12-extrude',track:'mechanical',title:['从轮廓到实体：拉伸、切除和特征顺序','From profile to solid: extrude, cut and feature order'],pre:['m12-parameters'],bench:'geometry',goal:['建立有厚度、有通孔、能回到草图修改的安装板。','Create a thick mounting plate with through-holes and editable sketch history.'],terms:[['特征','Feature','拉伸、孔等可编辑建模步骤。','An editable modeling step such as an extrusion or hole.'],['实体','Body','由封闭边界描述的几何体。','Geometry bounded by a closed solid boundary.']],sections:[
['先看轮廓再看方向','Check region and direction','结束草图，选板区域并拉伸thickness=3 mm。Fusion选择New Body；SW选Extruded Boss/Base。看箭头确认材料向哪个方向增加，避免整个板与安装基面错开。建立完用截面或侧视确认不是只有一张面。','Finish the sketch and extrude the plate region by thickness=3 mm. Use New Body in Fusion or Extruded Boss/Base in SOLIDWORKS. Check the direction arrow and side view so the result is a solid aligned to its mounting face.'],
['通孔优先表达“穿透”','Express a through-hole as through-all','在板面或稳定基准面画两个圆，再做Cut，终止条件用All/Through All。若只切3 mm，后来板厚改5 mm可能变成盲孔。选择谁被切也要确认，多实体设计里不能误切邻近零件。','Sketch circles on a face or stable reference plane and cut with All/Through All. A fixed 3 mm cut can become blind when thickness grows to 5 mm. Verify the affected body so neighbouring parts are not cut accidentally.'],
['添加与删除不是同一操作','Adding and removing material differ','Join把新体积并入旧实体，Cut移除材料，New Body保留独立实体。预览颜色只作辅助，最终检查Browser中的实体数量和剖面。SW的Merge result控制可合并的拉伸结果，Cut仍是另一类特征。','Join adds connected volume, Cut removes it and New Body keeps a separate solid. Check body count and a section after previewing. SOLIDWORKS Merge result controls merging compatible boss geometry; an extruded cut is a distinct operation.'],
['让历史保持可读','Keep feature history readable','把草图改名plate_outline，拉伸改名plate_thickness，切孔改名mount_holes。修改早期草图后逐个检查后续特征是否重建。装饰圆角放在基本功能尺寸之后，减少后面引用到易消失的小边。','Rename the outline, thickness and mounting-hole features. After editing an early sketch, inspect downstream rebuilds. Add cosmetic fillets after functional geometry to reduce references to small edges likely to disappear.'],
['用厚度变更验收','Accept by changing thickness','把厚度3改5 mm，检查通孔仍贯穿、底面仍贴基准、零件数量不变。操作台只计算简化双孔板的体积，不是CAD布尔内核；真实模型仍需在Fusion或SW完成并保存。','Change thickness from 3 to 5 mm. Verify holes still pass through, the mounting face remains on its datum and the part count is unchanged. The bench calculates a simplified two-hole plate, not a CAD Boolean kernel; save the real CAD model separately.']
],example:['净截面积40×30−2π×2²≈1174.87 mm²，厚度3变5，净体积从3524.60变5874.34 mm³，比值5/3。','Net section area is 1174.87 mm². Increasing thickness from 3 to 5 mm changes volume from 3524.60 to 5874.34 mm³, in the ratio 5/3.'],exercise:['做3 mm板、贯通切孔，再改5 mm并出一张剖视截图。','Make a 3 mm plate with through-holes, change it to 5 mm and capture a section view.'],acceptance:['孔持续贯通；特征有名称；解释固定深度与贯穿的区别。','Holes remain through, features are named, and fixed-depth versus through-all is explained.'],refs:['extrude','swextrude'],quiz:[q(['板厚增加后仍要通孔，应选？','To retain through-holes after thickness changes?'],[['原厚度固定切深','Cut to old thickness'],['贯穿全部','Through All'],['只画圆不切','Draw circles only']],1,['终止条件表达设计意图。','The end condition expresses intent.']),q(['体积随固定截面积的厚度变化是？','With fixed section area, volume varies with thickness?'],[['线性','Linearly'],['平方','Quadratically'],['无关','Unrelated']],0,['V=A×t。','V=A×t.'])]});
add({id:'m12-revolve',track:'mechanical',title:['轴套与圆角：旋转成形和细节尺度','Sleeves and fillets: revolved forms and detail size'],pre:['m12-extrude'],bench:'revolve',goal:['用剖面与轴线制作隔离柱，并解释内外径和圆角余量。','Make a spacer from a profile and axis, explaining diameters and fillet space.'],terms:[['旋转轴','Axis of revolution','剖面绕其转动形成体积的直线。','The line around which a profile creates volume.'],['圆角','Fillet','用圆滑过渡替代相交锐边的特征。','A rounded transition replacing a sharp edge.']],sections:[
['从半剖面理解旋转','Understand a half-section','把圆筒沿轴线剖开，半边材料是一个长方形：靠轴边距离为内半径，远轴边为外半径，长度是柱高。不要把直径直接作为到轴距离，否则实物会大一倍。','A tube half-section is a rectangle offset from its axis. The near distance is inner radius, the far distance outer radius and its length the height. Entering diameter as axis distance doubles the intended diameter.'],
['在原生软件选择剖面与轴','Select profile and axis in CAD','Fusion用Revolve选择闭合剖面和构造轴，角度360°；SW用Revolved Boss/Base，选择中心线。先预览完整柱，再尝试180°理解角度控制的是扫过范围，而不是把柱高度减半。','In Fusion Revolve, select the closed profile, construction axis and 360°. In SOLIDWORKS use Revolved Boss/Base with a centreline. Preview 180° to see the swept angle change rather than interpreting it as half the height.'],
['内外径决定壁厚','Diameters determine wall thickness','外径10、内径4 mm，单侧壁厚(10−4)/2=3 mm。内径必须小于外径；内外径相等时体积为零，不是一个可用的薄壁实体。孔留多少间隙需按实际配合和工艺验证。','For outside diameter 10 and bore 4 mm, wall thickness is (10−4)/2=3 mm. Bore must be smaller than outside diameter; equality gives zero solid volume. Required clearance depends on the real fit and process.'],
['圆角和倒角有不同用途','Fillets and chamfers differ','圆角使边缘平滑，倒角用斜平面破边或帮助导入。先在不承担定位的外边试0.5 mm，确认没有吃掉螺帽支承面或薄壁。圆角半径越大不一定越好；功能面要保留。','Fillets round an edge; chamfers create a sloping flat for edge relief or entry. Try an illustrative 0.5 mm on a nonlocating outer edge and confirm seating faces and thin walls remain. Larger fillets are not always better.'],
['导出前检查剖面','Inspect a section before export','显示轴向剖面，看孔是否连续、壁厚是否一致、有没有孤立碎体。教学操作台用SVG投影展示完整轴套并计算理想体积，不模拟刀具或应力。实际倒角与圆角会改变体积，应在真实CAD中再测。','Inspect an axial section for a continuous bore, consistent wall and stray solids. The SVG bench shows a complete sleeve and ideal volume without tool or stress simulation. Actual fillets and chamfers change volume and must be checked in CAD.']
],example:['外径10、内径4、高12 mm，体积π(5²−2²)×12=252π≈791.68 mm³；壁厚3 mm。','With OD 10, ID 4 and height 12 mm, volume=π(5²−2²)×12=791.68 mm³; wall thickness is 3 mm.'],exercise:['完成隔离柱；将内径4改5 mm，说明体积与壁厚怎样变化。','Model the spacer, change bore 4 to 5 mm and explain the change in volume and wall thickness.'],acceptance:['能正确选轴和剖面；解释半径直径；提交剖视及一个变式。','Correct axis/profile selection, radius/diameter explanation and one varied section view.'],refs:['revolve','swrevolve'],quiz:[q(['外径10、内径4的单侧壁厚？','Wall thickness for OD10 and ID4?'],[['6 mm','6 mm'],['3 mm','3 mm'],['14 mm','14 mm']],1,['直径差要除以二。','Divide the diameter difference by two.']),q(['绕轴360°意味着？','A 360° revolution means?'],[['完整旋转一周','One complete sweep'],['高360 mm','360 mm height'],['壁厚360 mm','360 mm wall']],0,['旋转角度与长度单位不同。','Angle and length are different quantities.'])]});
add({id:'m12-components',track:'mechanical',title:['从零件到装配：组件、固定与连接','Parts into assemblies: components, grounding and connections'],pre:['m12-revolve'],bench:'joint',goal:['把底座、摆臂和轴拆成独立组件，建立一个可控转动副。','Separate base, arm and pin into components and create a controlled revolute joint.'],terms:[['组件','Component','带自身坐标、可参与装配关系的零件容器。','A part container with its own coordinates and assembly relationships.'],['接地/固定','Ground/fix','将一个基准组件相对装配坐标锁定。','Lock a reference component to assembly coordinates.']],sections:[
['先列零件清单','List physical parts first','同一块连续材料通常是一个零件；需要相对运动的底座和摆臂应分开。先写base、arm、pin三个名称，说明谁制造、谁购买。不要为了画面方便把所有东西Join成一块。','A continuous manufactured piece is usually one part; a base and moving arm should be separate. Name base, arm and pin and mark made versus purchased items. Joining everything into one solid eliminates the intended assembly.'],
['实体与组件不是同义词','Bodies and components differ','Fusion中把每个实体放进对应组件，激活目标组件再画它的草图；SW通常分别保存零件，再插入装配体。共享一个文件并不代表物理上是同一件；名字和坐标会帮助以后替换零件。','In Fusion place each body inside its component and activate it before sketching. In SOLIDWORKS, save parts and insert them into an assembly. Sharing a file does not make parts physically continuous; names and coordinates make later replacement manageable.'],
['固定底座，不固定所有件','Fix the base, not everything','先固定底座作为参考，移动摆臂观察仍有什么自由度。若全部固定，画面看似稳定但机构无法动。若没有参考固定，拖动一个件可能带动整个装配漂走，掩盖关系错误。','Fix the base as reference and inspect arm freedom. Fixing every part makes a static picture, not a mechanism. With no grounded reference, dragging may move the whole assembly and hide relationship errors.'],
['关节表达允许怎样运动','A joint specifies allowed motion','Fusion选两个组件的轴心建立Revolute关节。SW可用Concentric配合对齐孔轴，再用Coincident或Distance配合限制轴向移动，并保留转动自由度。两种软件概念相通但命令不是一对一复制。','Use a Fusion Revolute joint between component axes. In SOLIDWORKS, a concentric mate aligns axes and a coincident/distance mate restricts axial translation while leaving rotation. These concepts correspond, but their commands are not identical.'],
['用动作检查装配意图','Check intent through movement','在操作台改变角度，看摆臂端点绕轴走圆弧；底座不应移动。回到0°后检查接线预留空间。该演示只有理想几何运动，不包含碰撞、摩擦、轴承间隙或电机扭矩。','Change the bench angle and watch the arm endpoint follow an arc while the base remains still. Reset to 0° and consider cable space. This is ideal kinematics without collision, friction, bearing clearance or motor torque.']
],example:['长40 mm摆臂转60°，相对轴心端点x=40cos60°=20 mm，y=40sin60°≈34.64 mm。','A 40 mm arm at 60° has endpoint x=20 mm and y≈34.64 mm relative to its pivot.'],exercise:['装配base、arm、pin，固定base，仅让arm绕轴转动；记录仍允许与禁止的动作。','Assemble base, arm and pin, fix base and allow only arm rotation; document permitted and prevented motions.'],acceptance:['底座固定；摆臂不窜轴；能返回初始姿态；明确运动演示不证明结构强度。','Base fixed, no axial arm drift, reset works, and motion demonstration is distinguished from strength validation.'],refs:['joint','swmate'],quiz:[q(['底座与摆臂需要相对转动，应？','For base and arm to rotate relatively?'],[['合并成单实体','Join into one body'],['全固定','Fix everything'],['分组件并建立转动关系','Separate components with a rotational relationship']],2,['相对运动需要独立组件和适当约束。','Relative motion needs separate components and suitable constraints.']),q(['仅有同轴配合可能还剩？','A concentric mate alone may still allow?'],[['轴向移动和转动','Axial movement and rotation'],['材料熔化','Melting'],['文件自动导出','Automatic export']],0,['还需根据装配意图限制轴向位置。','Constrain axial location as required by the assembly.'])]});
add({id:'m12-motion',track:'mechanical',title:['运动范围与干涉：能动不等于能用','Motion limits and interference: movement is not usability'],pre:['m12-components'],bench:'joint',goal:['按任务定义角度范围，检查端点、干涉和线缆空间。','Define a task-based angle range and inspect endpoints, interference and cable space.'],terms:[['运动学','Kinematics','只描述位置、速度关系，不必求力。','Descriptions of position and motion without necessarily solving force.'],['干涉','Interference','不应重叠的实体占用了同一空间。','Unwanted solid overlap in space.']],sections:[
['先写扫描范围','Define the useful sweep','假设传感器只需左右各45°，先规定−45°到45°，再调几何。不能因为软件能转360°就允许线缆绕满一圈；接插件、止挡和人体接近区也占空间。','For a sensor scanning 45° each way, define −45° to 45° before refining geometry. A software joint capable of 360° does not permit cables to wrap indefinitely; connectors, stops and access also occupy space.'],
['给关节设置限位','Set limits deliberately','Fusion编辑Motion Limits；SW按需求使用Limit Angle/Limit Distance等配合。最小、最大和起始角是三个不同值。检查单位为度并明确正方向，截图标示0°对应的实际姿态。','Edit Fusion Motion Limits or appropriate SOLIDWORKS limit mates. Minimum, maximum and initial angles are different values. Confirm degrees and positive direction, and mark the physical pose corresponding to 0°.'],
['慢速检查全行程','Inspect the full path slowly','检查最小角、0°、最大角以及中途可能接近障碍的位置。一个端点无干涉不能证明整条路径安全。用原生CAD的干涉或截面工具核对几何，软件未启用接触时仍可能允许物体穿过彼此。','Inspect minimum, zero, maximum and intermediate near-obstacle poses. Clear endpoints do not prove a clear path. Use native interference/section tools; without contact handling, software may allow objects to pass through each other.'],
['力矩问题另算','Torque is a separate question','若末端有质量，静止时也可能需要力矩。示例0.1 kg质量在水平0.04 m处，重力矩约0.1×9.81×0.04=0.039 N·m；这没有包含加速、摩擦、碰撞或裕量，不能直接当电机选型结论。','A load may require torque even at rest. An illustrative 0.1 kg at a horizontal 0.04 m gives about 0.039 N·m gravitational torque. This excludes acceleration, friction, impact and margin, so it is not a motor selection result.'],
['保存姿态和检查结果','Save poses and findings','输出一张姿态表：角度、最小间隙、线缆弯曲、观察问题。操作台支持播放、暂停和复位；它只改变角度和端点坐标，不计算碰撞。把需要真实验证的项目列到装配验收单。','Keep a pose table with angle, minimum clearance, cable bending and observations. The bench plays, pauses and resets angle and endpoint coordinates only, without collision computation. Carry physical checks into the assembly checklist.']
],example:['40 mm摆臂在±45°，两端点横向同为28.28 mm，纵向相差56.57 mm；这不是直线导轨行程。','For a 40 mm arm at ±45°, endpoint x is 28.28 mm at both limits and y span is 56.57 mm; the path is still an arc, not a linear slide.'],exercise:['以−45°至45°设计扫描范围，检查5个姿态并记录真实CAD中的最小间隙。','Define a ±45° scan and inspect five poses, recording minimum clearance from native CAD.'],acceptance:['有范围、正方向、初始姿态和至少5个检查点；不把播放成功当承载验收。','State limits, direction, initial pose and five inspected points; animation success is not a load test.'],refs:['joint','swmate'],quiz:[q(['动画能顺畅播放证明？','Smooth animation proves?'],[['电机扭矩足够','Enough motor torque'],['零件绝不碰撞','No possible collision'],['所设置运动能被显示','The configured motion can be displayed']],2,['力、接触和真实间隙必须另行检查。','Forces, contacts and actual clearance require separate checks.']),q(['重力矩与水平力臂的关系？','Gravity torque versus horizontal lever arm?'],[['τ=mgr','τ=mgr'],['τ=m/r','τ=m/r'],['τ=r/m','τ=r/m']],0,['这里r是力方向垂直的力臂。','Here r is the moment arm perpendicular to force.'])]});
add({id:'m12-drawing',track:'mechanical',title:['工程图与公差：让别人做得出来','Drawings and tolerances: make the design reproducible'],pre:['m12-motion'],bench:'geometry',goal:['输出带视图、关键尺寸、公差、单位与版本的零件图。','Create a part drawing with views, critical dimensions, tolerances, units and revision.'],terms:[['公差','Tolerance','允许尺寸变化的范围。','The permitted range of dimensional variation.'],['尺寸链','Dimension chain','相互关联尺寸形成的累计关系。','A chain of related dimensions and accumulated variation.']],sections:[
['三维截图不是加工图','A render is not a manufacturing drawing','准备正视、俯视和必要剖视，让孔是否贯通、台阶在哪里都能辨认。标明mm、材料、数量和修订号。缩放后的截图不能让制造者拿尺子量屏幕猜尺寸。','Provide orthographic and necessary section views so holes and steps are unambiguous. State millimetres, material, quantity and revision. A scaled screenshot cannot substitute for dimensions by measuring the screen.'],
['从模型创建关联图纸','Create a model-linked drawing','Fusion使用Drawing > From Design创建图纸，再放基础视图和投影视图；SW用Make Drawing from Part/Assembly并放模型视图。选足够容纳尺寸的比例，图纸比例变了，标注的真实尺寸不能随之改变。','Create a Fusion drawing from the design, or a SOLIDWORKS drawing from the part/assembly, then place base and projected views. Choose a scale with space for annotations; changing view scale must not change the actual dimension values.'],
['从共同基准定位孔','Locate holes from common datums','孔中心位置优先从功能基准标注，避免用一串不必要的链式尺寸。孔径写直径符号，深度说明通孔或盲孔。不要在多个视图重复互相矛盾的控制尺寸；参考尺寸应明确为参考。','Locate holes from functional datums rather than unnecessary dimension chains. Mark diameters and through/blind depth. Avoid contradictory controlling dimensions across views; distinguish reference dimensions from requirements.'],
['公差来自功能与能力','Choose tolerance from function and process','例如孔4.20±0.10 mm允许4.10到4.30，轴4.00±0.05允许3.95到4.05，最小直径间隙0.05 mm，最大0.35 mm。示例不是通用配合标准；打印孔是否达到范围必须实测。','A 4.20±0.10 mm hole spans 4.10–4.30 and a 4.00±0.05 shaft spans 3.95–4.05, giving 0.05–0.35 mm diametral clearance. This is an example, not a standard fit designation; printed holes require measurement.'],
['发布前按图重建','Reconstruct before releasing','遮住三维模型，只看图纸尝试定位每个功能面和孔。缺少尺寸就补充，存在冲突就回到设计意图。导出PDF后以实际页面重新打开，检查字体、截断、版本与单位，并保留可编辑源文件。','Hide the 3D model and try to locate every functional face and hole from the drawing. Add missing information and resolve conflicts. Reopen the exported PDF to inspect fonts, clipping, revision and units, keeping the editable source.']
],example:['上述孔轴最小间隙=4.10−4.05=0.05 mm；最大=4.30−3.95=0.35 mm。不能只用名义值0.20 mm判断全部组合。','Minimum clearance=4.10−4.05=0.05 mm; maximum=4.30−3.95=0.35 mm. Nominal 0.20 mm alone does not describe all combinations.'],exercise:['为安装板出一页图纸，给两个关键尺寸合理的示例范围，再计算最坏组合。','Create a one-page plate drawing, assign justified example ranges to two critical dimensions and calculate corner cases.'],acceptance:['单位、版本、投影方向和孔定义完整；能从图纸重建；公差有理由而非全部±0.01。','Units, revision, projection and holes are defined; reconstructable geometry and justified tolerances rather than universal ±0.01.'],refs:['drawing','measure'],quiz:[q(['孔最小4.10、轴最大4.05，最小直径间隙？','Hole min4.10, shaft max4.05: minimum diametral clearance?'],[['0.05 mm','0.05 mm'],['0.20 mm','0.20 mm'],['0.35 mm','0.35 mm']],0,['最紧配合取最小孔与最大轴。','The tightest case pairs smallest hole with largest shaft.']),q(['把图纸比例从1:1改1:2，40 mm标注应？','Change scale 1:1 to 1:2; a 40 mm dimension should?'],[['变20','Become20'],['保持40','Remain40'],['删除','Be deleted']],1,['图形缩小，真实尺寸不变。','The view shrinks, not the real dimension.'])]});
add({id:'m12-fasteners',track:'mechanical',title:['螺丝、孔与装配顺序','Screws, holes and assembly sequence'],pre:['m12-drawing'],bench:'geometry',goal:['选清通孔与螺纹孔，检查螺丝长度、工具空间与可维护性。','Distinguish clearance/tapped holes and inspect screw length, tool access and maintainability.'],terms:[['螺距','Pitch','相邻螺纹牙沿轴向的距离。','Axial distance between adjacent thread crests.'],['夹持厚度','Grip thickness','螺栓头与螺母之间夹住的总厚度。','Total stack thickness clamped between head and nut.']],sections:[
['先看连接要做什么','State what the joint must do','支架上的螺丝可能夹紧两件，也可能只当转轴；两者设计不同。普通夹紧不能靠拧到塑料明显凹陷证明可靠，转轴也不能随意用全螺纹杆摩擦软塑料孔。先画力如何传递。','A screw may clamp parts or act as an axle; these need different designs. Crushing plastic is not evidence of a good clamp, and a fully threaded shank rubbing a soft bore is not automatically a good pivot. Sketch the load path first.'],
['M3不是孔径3 mm的命令','M3 is not a universal 3 mm hole','M表示公制螺纹，数字是公称直径；螺距、头型、长度和材料等级仍要确定。通孔要让螺杆通过，攻丝底孔要按螺纹与材料工艺选。两类孔不能用同一个直径随意替代。','M indicates metric thread and the number nominal diameter; pitch, head, length and material grade remain to be specified. A clearance hole passes the screw, while a tapping drill is selected for the thread and process. They are not interchangeable.'],
['长度包含哪些层','Account for the whole stack','以非沉头螺栓示例，长度通常从头下到端部；沉头长度规则不同，查型号图。列出板、垫片、螺母或螺纹啮合段，确认既能啮合也不会顶到盲孔底。不要把“拧不动”一律当夹紧到位。','For a typical noncountersunk bolt, length is measured under the head to the tip; countersunk conventions differ. List plates, washers, nut or engaged thread length, checking engagement and blind-hole bottoming. Resistance to turning can mean bottoming, not proper clamping.'],
['工具也占空间','Tools need clearance too','在CAD中预留螺丝刀或内六角扳手进入方向、螺母安装路径和手指取放空间。装配顺序如果要求先封壳再拧内部螺丝，就是可制造性问题。先用纸片或低成本打印件模拟装拆。','Reserve driver/hex-key approach, nut insertion and handling space. A sequence requiring internal screws after sealing the housing is an assembly problem. Rehearse installation and removal with paper or an inexpensive prototype.'],
['拧紧条件必须有出处','Tightening conditions need evidence','扭矩取决于螺纹、材料、摩擦、润滑和连接件，不能仅按M3给所有连接一个数值。查紧固件与被连接件要求；打印塑料还需考虑层向和长期蠕变。记录型号、安装方式、异常与复检周期。','Torque depends on thread, material, friction, lubrication and joint; M3 alone does not justify one universal value. Follow fastener and joint requirements. Printed plastic also needs layer-direction and creep consideration; record part numbers, assembly and reinspection.']
],example:['两板3+2 mm、两垫片各0.5 mm、螺母厚2.4 mm，几何堆叠8.4 mm；10 mm螺栓剩约1.6 mm。仍需核对实际螺母、倒角、有效螺纹及安装空间。','Two plates 3+2 mm, two 0.5 mm washers and a 2.4 mm nut total 8.4 mm. A 10 mm bolt leaves about 1.6 mm, subject to real nut dimensions, chamfers, usable thread and access.'],exercise:['为支架做一张爆炸装配草图和BOM，检查每颗螺丝从哪里进入、怎样拆下。','Make an exploded sketch and BOM, checking how every screw is installed and removed.'],acceptance:['通孔/螺纹孔正确区分；长度有堆叠依据；无凭空给出的通用扭矩。','Correct hole types, a documented length stack and no invented universal torque.'],refs:['fastener','swmate'],quiz:[q(['拧到底但零件仍松，可能是？','Screw stops turning while parts remain loose: possible cause?'],[['盲孔底碰到螺丝端','Tip bottomed in blind hole'],['必定正确夹紧','Definitely clamped'],['无需检查','No inspection needed']],0,['先核对长度和啮合，不要继续强拧。','Check length and engagement before applying more force.']),q(['选择紧固扭矩只看M3足够吗？','Is M3 alone enough to select torque?'],[['足够','Yes'],['不够','No'],['只看颜色','Only colour matters']],1,['材料、摩擦和连接结构也会改变要求。','Material, friction and joint design affect requirements.'])]});
add({id:'m12-slice',track:'mechanical',title:['切片入门：层高、外墙、填充和摆放','Slicing basics: layers, walls, infill and orientation'],pre:['m12-fasteners'],bench:'slice',goal:['读懂逐层预览，解释层高、外墙与填充分别改变什么。','Read a layer preview and explain what layer height, walls and infill change.'],terms:[['切片','Slicing','把几何模型转成逐层制造路径的处理。','Converting geometry into layer-by-layer manufacturing paths.'],['外墙/轮廓','Perimeter','每层围绕外边界的挤出路径。','Extrusion paths following a layer boundary.']],sections:[
['从模型到机器文件有中间步骤','A model needs process preparation','从CAD导出STL或3MF时核对单位与网格质量，在切片器选择真实打印机、喷嘴和材料配置。网格文件不等于可直接打印的机器指令；不要把别的机器的G-code当通用文件。','Export STL or 3MF with verified units and mesh quality, then select the actual printer, nozzle and material profile. A mesh is not a machine program; another printer’s G-code is not a universal input.'],
['先选摆放再选细节','Choose orientation before fine tuning','把需要平整的面朝下，同时考虑层间受力、悬垂、接触面积和表面要求。一个方向支撑少，可能让关键载荷跨层拉开；没有一个方向同时优化所有指标，记录取舍。','Choose orientation for flatness, load direction, overhangs, bed contact and surface needs. Fewer supports may orient critical tension across layers. Record the tradeoff rather than assuming one orientation optimizes everything.'],
['层高主要控制竖直分层','Layer height controls vertical discretization','10 mm高的简化方块，统一0.2 mm层高需要50层；0.1 mm为100层。层高变小不自动提高XY细小文字分辨率，也不直接让零件更结实。实际首层可能不同，必须看逐层预览。','A simplified 10 mm block with uniform 0.2 mm layers needs 50 layers; 0.1 mm needs 100. Smaller layer height does not automatically improve XY text detail or strength. Real first-layer height can differ, so inspect the preview.'],
['外墙与填充不是替代品','Walls and infill serve different roles','外墙形成外壳，顶底实心层封住表面，内部填充支撑顶层并影响刚度与用料。示例线宽0.45 mm、3圈外墙，名义墙厚约1.35 mm；真实路径可能自适应，不能只用填充100%替代设计检查。','Perimeters form the shell, solid top/bottom layers close surfaces and infill supports tops while affecting stiffness and material. At illustrative 0.45 mm line width and three walls, nominal wall thickness is 1.35 mm; adaptive paths can differ. Full infill does not replace design checks.'],
['逐层找断岛和悬空','Inspect layers for islands and unsupported regions','拖动层滑块检查第一层、孔顶、悬垂起点及最终顶层。记录哪里需要支撑、哪里有空走。课程操作台只有矩形体几何分层和理想体积估算，不输出G-code、不预测实际时间或强度。','Scrub the first layer, hole roofs, overhang starts and final top. Identify support needs and travel. The bench only illustrates rectangular layering and ideal material volume; it generates no G-code and predicts neither actual time nor strength.']
],example:['20×20×10 mm方块，0.2 mm层高50层；外墙1.35 mm后内区17.3×17.3 mm。顶底各0.6 mm、填充20%时，可用几何体积预算比较材料趋势。','A 20×20×10 mm block at 0.2 mm has 50 layers. A 1.35 mm shell leaves a 17.3×17.3 mm interior. With 0.6 mm top/bottom and 20% infill, an ideal volume budget compares material trends.'],exercise:['比较0.1/0.2 mm层高与2/4圈外墙，保存4组层数、名义墙厚和路径观察。','Compare 0.1/0.2 mm layers and two/four perimeters, recording four layer counts, nominal wall thicknesses and path observations.'],acceptance:['能区分外墙/填充/顶底；真实切片配置和单位明确；知道估算不等于制造验证。','Distinguish walls, infill and caps; identify real printer settings and units; separate estimates from manufacturing verification.'],refs:['slice'],quiz:[q(['10 mm、统一0.2 mm层高需要？','10 mm at uniform 0.2 mm layers needs?'],[['5层','5 layers'],['50层','50 layers'],['500层','500 layers']],1,['层数=高度/层高。','Layer count=height/layer height.']),q(['层高减半一定使XY细节翻倍吗？','Does halving layer height double XY detail?'],[['不一定','No'],['一定','Yes'],['与喷嘴无关','Nozzle never matters']],0,['XY路径与喷嘴、线宽和几何也有关。','XY detail also depends on nozzle, line width and geometry.'])]});
add({id:'m12-calibrate',track:'mechanical',title:['首层与缺陷：用对照实验调打印','First layers and defects: diagnose through controlled tests'],pre:['m12-slice'],bench:'slice',goal:['辨认首层、翘边、拉丝和尺寸偏差，用一次一变量的记录排错。','Recognize first-layer issues, warping, stringing and dimensional error using controlled comparisons.'],terms:[['首层','First layer','与打印平台接触并支撑后续结构的一层。','The layer contacting the build surface and supporting later layers.'],['翘曲','Warping','收缩与约束不均造成角部或整体变形。','Deformation caused by uneven contraction and restraint.']],sections:[
['先照设备流程准备','Follow the printer-specific setup','确认喷嘴和平台状态、材料配置、平台清洁方式与调平流程。手动Z偏移与自动力传感首层不是同一操作，不能照另一个型号教程强行改值。热端、平台和运动部件操作按设备说明进行。','Check nozzle, bed, material profile, cleaning and leveling according to the actual printer. Manual Z-offset and load-cell-based calibration are different workflows; do not copy another model’s adjustments. Follow device instructions around hot and moving parts.'],
['看相邻线是否合理结合','Inspect neighbouring first-layer lines','喷嘴过高可能留下圆条和缝隙；过低可能挤出脊、刮擦或不均。先打印小测试片观察，而不是失败后连续改十个参数。平台脏、材料潮湿、挤出不足也可能影响结果，症状不对应唯一原因。','Excess height can leave rounded separated lines; too low can cause ridges, scraping or uneven extrusion. Use a small test piece before changing many settings. Dirt, moisture and extrusion problems can produce overlapping symptoms, so avoid single-cause assumptions.'],
['翘边先看接触与温差','Investigate contact and temperature differences','角部抬起时记录材料、模型底面积、平台处理和气流。按材料配置检查温度与附着，再考虑边缘辅助结构和摆放。不要无限升温掩盖原因，也不要把所有材料封闭打印当万能解法。','For lifting corners, record material, footprint, surface treatment and airflow. Check the material’s temperature and adhesion guidance, then consider brim or orientation. Unbounded temperature increases or enclosing every material is not a universal fix.'],
['拉丝用小样分离变量','Isolate stringing variables with a small test','细丝可能与温度、回抽、移动路径或材料状态有关。保留原配置，先按材料允许范围只改一个参数，记录照片与用时。若回抽过大可能引入其他送料问题，不应只追求一张照片看起来干净。','Stringing can involve temperature, retraction, travel and filament condition. Keep the baseline and vary one permitted setting on a small sample, recording photos and time. Excessive retraction can introduce feed problems, so judge more than surface appearance.'],
['尺寸补偿从试片开始','Start fit compensation with coupons','打印几个小孔和轴作为配合试片，冷却后测量并标注打印方向。外形准不保证孔准，全局缩放会一起改变孔距与外形。记录局部补偿和重复性后，再更新支架参数，并保留未修改的源模型。','Print bore/pin coupons, cool them and measure with orientation marked. Correct outer dimensions do not guarantee correct holes. Global scaling changes spacing and envelope too; record local compensation and repeatability before revising the bracket.']
],example:['设计孔4.20 mm，三次冷却后测4.02、4.04、4.03 mm，均值4.03，偏差−0.17 mm。单次试片不足以证明所有尺寸都应加0.17。','A designed 4.20 mm bore measures 4.02, 4.04 and 4.03 after cooling: mean4.03, error−0.17 mm. One coupon does not prove every dimension needs +0.17 mm.'],exercise:['选一种缺陷做基线和一次单变量对照，记录照片、配置、观察和下一步。','Choose one defect and record a baseline plus one single-variable comparison with photos, settings, observation and next step.'],acceptance:['区分现象与原因；不改未知设备参数；能说明新设置改善了什么、仍未证明什么。','Separate symptom and cause, avoid unsupported device settings and state both the improvement and remaining uncertainty.'],refs:['first','string','warp','measure'],quiz:[q(['排错时同时改温度、回抽、速度的缺点？','Why avoid changing temperature, retraction and speed together?'],[['难确定哪个改变起作用','Hard to identify the cause of improvement'],['必然更慢','Always slower'],['无法保存','Cannot save']],0,['对照实验需控制变量。','Controlled experiments isolate variables.']),q(['孔偏小可直接全局放大所有零件吗？','Should a small bore trigger global scaling of everything?'],[['必须','Always'],['先测并评估局部补偿','Measure and assess local compensation'],['不需量','No measurement needed']],1,['全局缩放也改变孔距和外形。','Global scaling also changes spacing and envelope.'])]});
add({id:'m12-project',track:'mechanical',title:['支架项目验收：从需求到可复现交付','Bracket capstone: requirements to reproducible handoff'],pre:['m12-calibrate'],bench:'geometry',goal:['交付可以修改、制造、装配和复查的支架项目。','Deliver an editable, manufacturable and reviewable bracket project.'],terms:[['BOM','Bill of materials','零部件、数量和型号清单。','A list of parts, quantities and identifiers.'],['修订','Revision','可追溯的设计版本与变更原因。','A traceable design version and change reason.']],sections:[
['先冻结最小可验收任务','Define a small acceptance target','给一个轻量传感器做桌面展示支架，写接口尺寸、姿态范围、环境和允许的试验条件。课堂件不用于承重人体、车辆制动或高能运动。范围写小，证据做完整，比宣称万能支架更有价值。','Build a desktop display bracket for a light sensor. State interface dimensions, motion range, environment and permitted testing. This classroom part is not for supporting people, vehicle braking or high-energy mechanisms. A narrow well-evidenced result is useful.'],
['整理设计决策','Organize the design decisions','将测量表、参数表、CAD源、装配关系和图纸关联到同一修订号。说明板厚、孔径和材料是来源明确的要求还是待验证假设。要求改变时先更新表，再改模型，避免图纸和模型各说各话。','Link measurement, parameter table, CAD, assembly and drawing to one revision. Mark thickness, holes and material as either sourced requirements or unverified assumptions. Update requirements before geometry so drawing and model stay consistent.'],
['制造前做数字检查','Inspect before fabrication','重建三种尺寸；检查闭合实体、组件命名、孔贯通、工具进入和运动范围。切片逐层检查首层、支撑和孔顶。教学几何台不能替代这些检查，截图必须注明来自原生CAD还是本课程模型。','Rebuild three sizes and inspect solids, names, through-holes, tool access and range. Scrub slicing at first layer, supports and bore roofs. The educational bench does not replace those checks; label native-CAD versus classroom-model evidence.'],
['实物检查保留失败记录','Keep physical failures as evidence','冷却后测关键尺寸，断电试装，手动缓慢移动到各检查姿态。记录卡住、松动、裂纹或线缆拉紧，修订后复验。模型漂亮不抵消装不上的孔，失败照片比只留成功渲染更能帮助下一人。','After cooling, measure critical dimensions, assemble unpowered and move slowly through inspected poses. Record binding, looseness, cracks or cable tension, then retest revisions. Attractive rendering does not compensate for unusable holes; keep failure evidence too.'],
['交付给一个没参与的人','Hand off to someone new','提供README：软件及版本、单位、入口文件、参数修改方法、制造配置、装配顺序、检查结果和限制。文件名用版本与用途，不包含真实姓名或本机路径。让同伴按README重建一个变体，把卡住处改成说明。','Provide a README with software version, units, entry file, parameter edits, manufacturing profile, assembly sequence, results and limits. Use revision/purpose filenames without personal names or machine paths. Have a newcomer rebuild a variant and improve unclear steps.']
],example:['v01孔实测偏小→v02只调孔参数→复测孔径与孔距→确认装配。若同时改材料、机器和所有尺寸，就无法把改善归因于孔参数。','v01 bore undersized → v02 changes only bore parameter → remeasure bore and spacing → check assembly. Changing material, printer and all dimensions together prevents attributing improvement.'],exercise:['交付源文件、PDF图、BOM、切片项目、测量记录和README；让同伴复现一个尺寸变体。','Deliver CAD, drawing PDF, BOM, slicer project, measurements and README; have another learner reproduce one size variant.'],acceptance:['第三人能找到入口、改参数、读图和装配；未做的实物验证明确标注，不能用“完成课程”替代。','A newcomer can find the entry, edit parameters, read drawings and assemble; unperformed physical validation is explicitly identified.'],refs:['parameter','drawing','slice','fastener'],quiz:[q(['最有用的项目交付是？','Most useful project handoff?'],[['只有美图','Only a render'],['源文件、说明、配置与验证记录','Sources, instructions, profiles and evidence'],['只有完成勾选','Only completion ticks']],1,['复现需要可编辑输入与可核对结果。','Reproduction needs editable inputs and checkable outputs.']),q(['v02只改孔径，目的是？','Why change only bore size in v02?'],[['隔离变量便于归因','Isolate the cause'],['隐藏失败','Hide failure'],['让文件更大','Make files bigger']],0,['保留基线能判断变化的实际效果。','A baseline makes the change assessable.'])]});
add({id:'o12-audience',track:'operations',title:['为谁做内容：受众、场景与行动','Who is this for? Audience, context and action'],pre:[],bench:'layout',goal:['把一次体验活动写成有明确受众与行动入口的内容简报。','Write a content brief with a clear audience and action for a workshop.'],terms:[['受众','Audience','在特定场景中需要这条信息的人。','People who need the information in a specific context.'],['行动入口','Call to action','希望读者完成的一个具体下一步。','The concrete next step requested from a reader.']],sections:[
['运营从问题开始','Start from a reader problem','假设工作室准备一次90分钟电子体验活动。先写谁来：没有接过面包板的初学者；他们担心什么：基础不够、需要买工具、怕跟不上。内容首先回答这些问题，不以堆满品牌词开场。','Imagine a 90-minute electronics workshop for people who have never used a breadboard. Their questions concern prerequisites, tools and pace. Answer those before filling the opening with branding language.'],
['目标要能观察','Make the goal observable','“扩大影响力”太难验收。课堂例子改成“在指定截止日前获得20个有效报名，并说明场地容量限制”。这是练习目标，不是承诺效果。报名、到场和完成作品是不同阶段，不能混成一个数字。','“Increase influence” is hard to assess. An exercise target could be 20 valid registrations by a stated deadline within venue capacity. This is a planning target, not a result promise. Registration, attendance and completed projects are separate stages.'],
['先写信息骨架','Write an information skeleton','用六句话回答：适合谁、能学到什么、何时何地、需要带什么、费用与人数、如何报名。所有未知项标“待确认”，不要为了版面完整编一个地址或价格。正文只保留一个主要行动入口。','Use six statements: audience, outcome, time/location, preparation, cost/capacity and registration. Mark unknown facts as pending rather than inventing a price or address to fill a layout. Keep one primary action.'],
['用语言降低门槛','Reduce uncertainty through language','把“沉浸式赋能创客生态”改成“现场接好一个能亮的LED电路，讲师带你检查接错的线”。承诺必须与实际课程和人员能力相符。使用具体动词、条件和结果，专业术语第一次出现就解释。','Replace vague promotional language with “wire a working LED circuit and diagnose mistakes with an instructor.” The promise must match the session and staff capability. Use concrete actions, conditions and outcomes, explaining new terms.'],
['先测试理解，再美化','Test comprehension before styling','请一位未参与策划的人读草稿30秒，复述活动对象、时间和报名方式。记录他找不到的内容，再调整顺序。操作台可修改标题与移动正文宽度，比较同样信息在不同版式下是否容易找到。','Ask someone outside the planning team to read for 30 seconds and restate audience, time and registration method. Record missing information before polishing. Use the bench to adjust title and mobile width while keeping the facts constant.']
],example:['原句“探索无限可能”无法回答来做什么；改为“零基础LED体验课｜90分钟完成接线与测量”，再补时间、地点、工具和报名入口。','“Explore endless possibilities” does not identify the activity. Try “Beginner LED workshop | wire and measure a circuit in 90 minutes,” followed by time, place, tools and registration.'],exercise:['为虚构活动写一页内容简报，并让另一人复述六个关键信息。','Write a one-page brief for a fictional event and ask another person to restate the six essential facts.'],acceptance:['受众与目标具体；未知信息没有捏造；行动入口清晰；有一次理解测试记录。','Specific audience/goal, no fabricated unknowns, a clear action and a recorded comprehension test.'],refs:['xiumi','canva'],quiz:[q(['哪个目标更可验收？','Which goal is more assessable?'],[['全面引爆','Go completely viral'],['提升格局','Transform the landscape'],['截止日前20个有效报名','20 valid registrations by deadline']],2,['需要明确指标、时间和有效定义。','Specify metric, time and a definition of valid.']),q(['地点尚未确定时应？','When the location is unknown?'],[['标待确认并在发布前落实','Mark pending and confirm before publishing'],['编一个地址','Invent an address'],['只做漂亮封面','Only design the cover']],0,['视觉完整不能掩盖信息缺口。','Visual completeness cannot hide missing facts.'])]});
add({id:'o12-assets',track:'operations',title:['素材与版权台账：知道每张图从哪里来','Asset provenance: know where every image comes from'],pre:['o12-audience'],bench:'layout',goal:['为图、字体、音乐和模板建立可复查的授权记录。','Create reviewable permission records for images, fonts, music and templates.'],terms:[['授权范围','License scope','许可的用途、平台、期限和限制。','Permitted uses, platforms, duration and restrictions.'],['素材台账','Asset register','把文件与来源、授权证据和使用位置关联的表。','A table linking assets to provenance, permissions and placement.']],sections:[
['能下载不等于能任意用','Downloadable does not mean unrestricted','搜索到图片、截图或模板不代表拥有发布与转售权。先优先使用自己制作且权利清楚的文字和几何图，再考虑平台授权素材。署名有时是要求，但署名本身不会自动取得授权。','Finding an image, screenshot or template does not grant publishing or resale rights. Prefer original text and geometry with clear rights, then properly licensed assets. Attribution may be required but does not itself grant permission.'],
['逐项保存来源证据','Record provenance per asset','台账列文件名、作者或平台、原始URL、取得日期、许可名称、允许用途、限制和证据文件。模板里的照片、字体和音乐可能有不同条件，不要只给整个文件写“网络来源”。','Record filename, author/platform, original URL, acquisition date, license, permitted use, restrictions and evidence. Photos, fonts and music inside one template can have different conditions; “from the internet” is not a usable record.'],
['平台素材按当前条款核对','Check current platform terms','Canva的Free、Pro、Education以及品牌素材不能只看是否能拖入画布就当同一授权；查具体素材信息与内容许可协议。秀米模板样式和示例文案也要分清，发布前换成自己的内容，别把样稿当现成宣传承诺。','Canva Free, Pro, Education and branded content do not have identical permissions merely because they can enter a canvas. Check item information and current license terms. In Xiumi, distinguish layout from sample copy and replace examples with your own verified content.'],
['人物与个人信息另查','Review people and personal information separately','活动照片还可能包含人脸、姓名牌、聊天记录和二维码。拍摄授权、公开发布范围与保存期限应由组织流程确认。练习只用虚构报名与自制图形，导出示例不包含真实联系方式或他人档案。','Event photos can expose faces, name badges, messages and QR codes. Confirm capture and publication permissions and retention through the organizer’s process. Practice with fictional registration and original geometry, excluding real contact details or learner archives.'],
['交付前逐个对应','Reconcile assets before handoff','把最终文章每张图与台账逐一对应，缺少来源的素材替换掉。保存授权证据不等于可以把原始付费素材打包送人；交付可编辑文件时检查接收方是否也需要自己的许可。','Match every final image to its register entry and replace unverified assets. Keeping a license record does not authorize distributing paid originals. Check whether recipients need their own permission before handing over editable files.']
],example:['asset_03.png：自制LED接线示意；作者“工作室教学组”；原始文件diagram_v02.svg；用于本次活动文章；无真人、无第三方商标。这样的记录比“网上找的”可复查。','asset_03.png: original LED wiring illustration, created by the teaching team, source diagram_v02.svg, intended for the event article, with no people or third-party marks. This is reviewable provenance.'],exercise:['给5份虚构或自制素材建台账；故意加入1项权限不明图片，写出替换决定。','Create a five-asset register using fictional/original assets and document replacing one asset with unclear rights.'],acceptance:['最终素材全部有出处；能区分署名、许可和转授权；不向外分享真实学员资料。','Every asset has provenance; distinguish attribution, license and redistribution; no real learner information is shared.'],refs:['canvaLicense','xiumiTerms'],quiz:[q(['给图片署名是否自动取得使用权？','Does attribution automatically grant usage rights?'],[['是','Yes'],['否','No'],['只要加水印就行','Adding a watermark is sufficient']],1,['仍需适用许可或权利人的授权。','An applicable license or permission is still needed.']),q(['付费模板可编辑文件交付前应检查？','Before sharing an editable paid-template file?'],[['仅文件大小','Only file size'],['是否足够漂亮','Only appearance'],['素材再分发与接收方许可','Redistribution and recipient licensing']],2,['获得使用许可不等于可转售或转赠所有原素材。','Permission to use does not necessarily permit redistributing original assets.'])]});
add({id:'o12-xiumi',track:'operations',title:['秀米与公众号：先结构，再移动预览','Xiumi and WeChat articles: structure, then mobile preview'],pre:['o12-assets'],bench:'layout',goal:['制作一篇信息完整、移动端可读、可交接的活动图文草稿。','Create an informative, mobile-readable and reviewable event article draft.'],terms:[['首屏','First screen','读者未滚动时看到的开头区域。','The initial area visible before scrolling.'],['层级','Hierarchy','用标题、正文和间距区分信息的重要性。','Importance expressed through headings, text and spacing.']],sections:[
['先分段，不先套模板','Structure before templates','把内容简报拆成导语、活动收获、时间地点、参与条件和报名说明。开头用一两句告诉读者值不值得继续看；把日期藏在末尾花字里会增加查找成本。每段只处理一个问题。','Turn the brief into introduction, outcomes, logistics, requirements and registration. The opening should establish relevance. Hiding the date in decorative footer text makes it harder to find. Let each paragraph answer one question.'],
['从官网新建图文草稿','Start a draft in the official editor','在秀米官网选择图文排版并新建图文，先放自己的文字，再加入必要图片和标题样式。保留一个主标题样式、一个小标题样式和正文样式；入口名称可能随云端版本变化，以当前界面为准。','From Xiumi’s official article editor create a draft, add your own copy, then necessary images and heading styles. Keep one main-heading style, one subheading style and body text. Cloud UI labels may change; follow the current interface.'],
['图片服务信息，不堵住阅读','Use images to explain, not obstruct','自制接线图旁写简短说明，避免把整篇正文做成一张无法选择或放大的长图。窄屏检查图片中文字是否能读，重要信息同时保留在正文。统一左右留白，避免每段换一种装饰。','Caption an original wiring image rather than converting the entire article into one long image. Check text inside images on a narrow screen and repeat critical information as real text. Keep consistent margins instead of changing decoration every paragraph.'],
['同步到公众号仍需复查','Transfer still requires review','按当前账号能力使用复制或已授权的同步流程，将内容送到公众号草稿后再看实际预览。授权同步不是发布成功，编辑器预览也不代表微信最终渲染。核对封面裁切、段落、图片、日期和链接。','Use the currently available copy or authorized synchronization workflow and review the resulting WeChat draft. Synchronization is not publication, and editor preview is not final platform rendering. Check cover crop, paragraphs, images, dates and links.'],
['用两种宽度检查同一篇','Check the same article at two widths','在课程版式台比较320与430 px，调正文大小、边距和行距，记录哪组更容易读。这里是本地排版练习，不连接公众号、不模拟平台审核。真实发布前还需在目标手机预览，确认跳转和报名表都正确。','Compare 320 and 430 px in the local layout bench, adjusting type, margins and line spacing. Record readability differences. This local exercise does not connect to WeChat or simulate moderation; review on a target phone and test registration links before publishing.']
],example:['320 px宽、左右各20 px，可用正文宽280 px；改成左右32 px只剩256 px。留白增多可能提升秩序，也会增加换行，必须同时看标题和段落。','A 320 px view with 20 px margins has 280 px text width; 32 px margins leave 256 px. More whitespace can improve organization but increases wrapping, so inspect headings and paragraphs together.'],exercise:['做一份虚构活动图文草稿，在两种宽度检查首屏、六项信息、图片说明和报名入口。','Make a fictional event article and inspect the first screen, six essentials, captions and action at two widths.'],acceptance:['内容有层级且完整；正文可读；标明未真实发布；交接包含源草稿和检查表。','Complete hierarchy, readable text, explicit unpublished status and a handoff containing draft and review checklist.'],refs:['xiumi','xiumiTerms'],quiz:[q(['编辑器预览通过后还需要？','After the editor preview looks correct?'],[['真实公众号草稿与目标手机复查','Review target-platform draft on a phone'],['无需复查','Nothing'],['直接群发','Immediately broadcast']],0,['不同平台可能改变样式、裁切与链接表现。','Platforms may alter styles, crops and links.']),q(['320 px宽左右各20，可用宽？','320 px width with 20 px on each side leaves?'],[['300 px','300 px'],['280 px','280 px'],['340 px','340 px']],1,['320−20−20=280。','320−20−20=280.'])]});
add({id:'o12-canva',track:'operations',title:['Canva版式：栅格、对齐与视觉主次','Canva layout: grids, alignment and hierarchy'],pre:['o12-xiumi'],bench:'layout',goal:['用统一栅格和少量样式完成活动海报，并检查导出效果。','Create an event poster with a consistent grid and inspect its export.'],terms:[['栅格','Grid','统一安排内容边界与间距的参考结构。','A reference structure for content edges and spacing.'],['安全边距','Safe margin','重要内容与边界保留的距离。','Space separating essential content from an edge.']],sections:[
['画布尺寸跟用途走','Choose a canvas for the destination','先确定发手机、投屏还是印刷，再设画布比例。竖版海报和公众号封面不是同一个裁切框。练习用360×480的逻辑画布讨论关系，不把它宣称为任何平台固定发布规格。','Decide whether the output is for phone, projection or print before choosing aspect ratio. A portrait poster and article cover have different crops. The 360×480 practice canvas illustrates relationships, not a fixed platform specification.'],
['用参考线建立共同边界','Create shared edges with guides','Canva桌面端可从File > Rulers and guides添加参考线或栅格。先设左右边界，再决定单列或两列；标题、图片和正文至少共享一条对齐线。不是所有元素都必须居中，左对齐往往更容易连续阅读。','In Canva desktop, add guides from File > Rulers and guides. Establish margins before one/two columns, and align headings, images and text to shared edges. Not every element needs centering; left alignment often supports continuous reading.'],
['只保留清楚的三级文字','Use a clear three-level type system','主标题负责主题，小标题组织信息，正文负责说明。不要靠每一行换字体制造重点；先调整字号、粗细与间距。把时间地点做成容易扫读的信息块，让读者不必在装饰中找关键事实。','Let title establish the topic, subheadings organize it and body text explain. Use size, weight and spacing rather than a new font on every line. Make logistics easy to scan instead of hiding them among decorative elements.'],
['颜色和图片都要可辨认','Keep colour and images legible','主色负责引导、背景负责承托，正文保持清晰对比。课程台提供三组配色与对比度读数，读数只检查设定的文字背景组合，不能自动证明整张海报可访问。手机预览还要看小字、图表和按钮。','Use accent for emphasis, background for support and readable body contrast. The bench reports contrast for its defined text/background pair only, not whole-poster accessibility. Inspect small type, graphics and action labels on a phone too.'],
['导出后再打开验收','Reopen the exported file','Canva通过Share > Download选择目标格式。静态PNG不会保留动作，印刷文件要和印厂核对尺寸、出血与色彩要求；某些选项依账号套餐不同。下载后重新打开，检查缺图、字体换行和裁切，不以“下载成功”为验收。','Use Share > Download and choose an appropriate format. Static PNG does not preserve motion; confirm print dimensions, bleed and colour requirements with the printer. Options vary by plan. Reopen the file to inspect missing assets, wrapping and crop.']
],example:['360 px画布、左右24 px、两列间隔16 px，每列=(360−48−16)/2=148 px；如果标题太长，先调整层级与文案，不把所有字缩到看不清。','For width360, margins24 and a16 px gutter, two columns are (360−48−16)/2=148 px each. If the title is long, revise hierarchy/copy before shrinking all text.'],exercise:['在版式台切换文章/海报、单列/两列和配色，保存两版并解释最终选择；再在Canva复现。','Compare article/poster, one/two columns and palettes in the bench, justify a chosen version, then reproduce it in Canva.'],acceptance:['有共同对齐线；信息主次明确；能算列宽；查看真实导出而非只看编辑页。','Shared alignment, clear hierarchy, calculated column width and inspection of the real export.'],refs:['canva','canvaExport'],quiz:[q(['360宽、两边24、列距16的两列宽？','360 width, margins24, gutter16: two-column width?'],[['148 px','148 px'],['156 px','156 px'],['180 px','180 px']],0,['先减双边距与一个列间距再除以二。','Subtract both margins and one gutter, then divide by two.']),q(['PNG能保留设计里的动画吗？','Does PNG preserve design animation?'],[['全部保留','All animation'],['静态PNG不能','A static PNG cannot'],['依文字大小','Depends on font size']],1,['输出格式决定支持的媒体能力。','Output format determines media capabilities.'])]});
add({id:'o12-event',track:'operations',title:['发布与活动执行：责任、检查与异常处理','Publishing and event execution: ownership, checks and exceptions'],pre:['o12-canva'],bench:'layout',goal:['为一次小型活动准备从草稿到现场再到归档的执行表。','Prepare an execution sheet from draft review through event delivery and archiving.'],terms:[['负责人','Owner','对某项任务的完成与交接负责的人。','The person responsible for completing and handing off a task.'],['运行表','Run sheet','按时间列任务、负责人和备选方案的清单。','A timeline of tasks, owners and fallback actions.']],sections:[
['一个任务一个明确负责人','Give each task a clear owner','列出文案、设计、审核、报名、场地和教学准备，给每项指定角色与完成时间。不要把“大家都看看”当审核流程；发布者应拿到明确版本和已确认事实。练习使用角色名，不收集真人电话。','List copy, design, review, registration, venue and teaching preparation with owners and deadlines. “Everyone take a look” is not a review workflow. The publisher needs a specific revision and confirmed facts. Practice with role names, not real phone numbers.'],
['发布前检查可见结果','Check the reader-facing result','核对标题、封面、日期、地点、费用、名额和报名截止，实点报名入口验证流程。先使用测试记录，再删除或标记测试数据，避免被算成真实报名。公众号权限和确认步骤按当前账号界面执行。','Check title, cover, date, venue, cost, capacity and deadline, then test the action path. Mark or remove test submissions so they are not counted as registrations. Follow the current account’s actual permissions and publication confirmation.'],
['容量与承诺要匹配','Match capacity to the promise','若可用工位8个，每组2人，课堂容量先按16人规划，再核对讲师与工具是否支持。设置候补与取消规则，避免为了报名数字超额接待。数量只是资源计划，现场还需满足组织要求。','Eight workstations with two people each suggest 16 participants before checking staffing and tools. Define waitlist and cancellation handling instead of overbooking to improve numbers. This is resource planning, subject to the organizer’s requirements.'],
['为常见异常留方案','Prepare practical fallbacks','列出投影失效、网络不可用、器材缺件、讲师延误时怎样继续。为离线资料、备用讲义和工具数量设检查人。不要在现场临时发所有人的联系方式到公开群，签到和通知只使用必要信息。','Plan for failed projection, no internet, missing tools and instructor delay. Assign checks for offline material and spares. Avoid exposing everyone’s contacts in a public group; use only necessary information for attendance and notices.'],
['活动结束不等于任务结束','Close the loop after the event','整理借还、问题清单、经确认可公开的照片和匿名汇总。把原始名单与公开复盘分开保存，按组织约定处理保留期限。对错误信息保留更正记录，不悄悄改掉后假装从未出错。','Reconcile borrowed items, issues, approved photos and anonymous totals. Keep raw rosters separate from public review and follow agreed retention. Preserve correction records rather than silently editing away mistakes.']
],example:['8工位×2人=16；报名20人时4人应进入有说明的候补流程，而不是默认20人挤进16人的工具配置。','Eight stations×two people=16. With20 registrations, four require an explicit waitlist process rather than assuming tools for16 serve everyone.'],exercise:['写一张T−7天、T−1天、活动中、T+1天运行表，每阶段包含负责人、产物和异常方案。','Write a T−7d, T−1d, event-day and T+1d run sheet with owner, deliverable and fallback at each stage.'],acceptance:['发布有人审核；入口测试完成；容量可解释；个人信息不混入公开复盘。','Reviewed publication, tested action path, explainable capacity and no personal data in the public review.'],refs:['xiumiTerms','canvaExport'],quiz:[q(['8工位每组2人，基础容量？','Eight two-person stations: basic capacity?'],[['8','8'],['16','16'],['无限','Unlimited']],1,['8×2=16，还要核对人员与工具。','8×2=16, with staffing/tool checks still required.']),q(['测试报名记录如何处理？','How should test registrations be handled?'],[['算进报名业绩','Count as real registrations'],['公开所有测试信息','Publish all test data'],['标记或清理，统计排除','Mark/remove and exclude from totals']],2,['测试数据不能污染实际指标。','Test data must not contaminate actual metrics.'])]});
add({id:'o12-review',track:'operations',title:['运营数据复盘：先定义分母，再解释变化','Reviewing results: define denominators before interpreting change'],pre:['o12-event'],bench:'layout',goal:['用匿名汇总计算报名、到场和完成率，提出可验证的下一步。','Calculate registration, attendance and completion rates from anonymous totals and propose a testable next step.'],terms:[['转化率','Conversion rate','同一范围内完成某步的人数除以上一步人数。','People completing a stage divided by the relevant prior-stage population.'],['口径','Metric definition','时间范围、去重、有效条件与分母的统一规则。','Consistent rules for period, deduplication, validity and denominator.']],sections:[
['把每个数字说完整','Define every number','记录统计时间、渠道、是否去重以及有效条件。阅读次数、独立读者、链接点击、有效报名和到场人数不是一回事。只有口径一致的数字才适合比较；平台不提供的指标不能靠猜补齐。','Record period, channel, deduplication and validity. Views, unique readers, clicks, valid registrations and attendance differ. Compare only compatible definitions and do not invent metrics unavailable from the platform.'],
['分母决定问题是什么','The denominator defines the question','200个独立读者、40个有效报名，读者到报名率20%；32人到场，到场/报名为80%，不是32/200的16%。两个比值都能计算，但分别回答不同问题。分母为0时显示不可计算，不写0%冒充结果。','With200 unique readers and40 valid registrations, reader-to-registration is20%. If32 attend, attendance/registration is80%, while32/200 is16%; these answer different questions. A zero denominator is undefined, not an observed0% result.'],
['把容量和渠道差异放回解释','Consider capacity and channel mix','如果活动限额16人，报名率低可能只是报名很快关闭；不能直接归因于海报不好。新老受众比例、推送时段和渠道变化也影响结果。先写已知条件，再列假设，避免用一个数字责怪某个人。','A16-person cap can lower apparent registration conversion after closure, without implying poor design. Audience mix, timing and channels also matter. State known conditions before hypotheses and avoid assigning blame from one metric.'],
['小样本不要过度解读','Avoid overinterpreting small samples','A版10人看、2人报名是20%，B版10人看、3人报名是30%，仅多1人。此结果可以提出后续测试，不能证明B版普遍提高50%。比较时尽量保持受众、时间和入口一致，并记录限制。','A gets2 registrations from10 readers, B gets3 from10:20% versus30%, only one extra person. This suggests further testing, not a general50% improvement claim. Keep audience, timing and action path comparable and record limitations.'],
['复盘必须落到下一次动作','Turn review into the next action','写三栏：观察、可能解释、下一步验证。例：多人询问是否需带工具→准备信息不显眼→下次把“工具现场提供”前移并做理解测试。公开报告只用匿名汇总，不附生日、答题明细或完整学员档案。','Use observation, possible explanation and next test. Repeated tool questions may suggest hidden preparation information; move “tools provided” earlier and retest comprehension. Publish anonymous aggregates, not birthdates, detailed answers or full learner archives.']
],example:['阅读200、报名40、到场32、完成24：报名率20%，到场率80%，到场者完成率75%。24/200=12%是全流程比例，不能把它命名为课堂完成率。','Readers200, registrations40, attendance32, completions24: registration20%, attendance80%, attendee completion75%. 24/200=12% is the end-to-end rate, not classroom completion rate.'],exercise:['用虚构数据写一页复盘，给每个比例标分母，再提出一个只改变一项内容的后续测试。','Write a one-page review with fictional data, label every denominator and propose a follow-up changing one content variable.'],acceptance:['公式和分母正确；零分母不伪造0%；区分事实、推断与计划；公开内容不含个人档案。','Correct formulas/denominators, honest zero-denominator handling, separation of facts/inference/plans and no personal archives.'],refs:['xiumi','canva'],quiz:[q(['报名40、到场32，到场率？','40 registrations and32 attendees: attendance rate?'],[['80%','80%'],['32%','32%'],['125%','125%']],0,['32/40=0.8。','32/40=0.8.']),q(['分母为0时应该？','With a zero denominator?'],[['写100%','Write100%'],['标不可计算并说明','Mark undefined and explain'],['写0%证明没效果','Write0% to prove failure']],1,['没有基数，比例无定义。','There is no base population for a defined rate.'])]});
const tracks=[
{id:'mechanical',title:['机械设计与制造','Mechanical design & fabrication'],summary:['测量 → 参数建模 → 装配运动 → 工程图 → 打印与验收；以传感器支架贯穿12课。','Measure → parametric CAD → assembly motion → drawings → printing and acceptance through a 12-lesson sensor bracket project.'],courseIds:courses.filter(c=>c.track==='mechanical').map(c=>c.id),prerequisites:[],hours:[36,60],deliverable:['可编辑CAD、图纸、BOM、切片与测量记录','Editable CAD, drawings, BOM, slicing and measurement records']},
{id:'operations',title:['内容设计与活动运营','Content design & event operations'],summary:['受众 → 素材 → 图文 → 海报 → 执行 → 数据；完成一份可交接的小型活动方案。','Audience → assets → article → poster → execution → review, producing a reproducible small-event plan.'],courseIds:courses.filter(c=>c.track==='operations').map(c=>c.id),prerequisites:[],hours:[18,30],deliverable:['简报、素材台账、文章、海报、运行表与匿名复盘','Brief, asset register, article, poster, run sheet and anonymous review']}
];
const scopes={geometry:['双孔板的理想几何与SVG投影；不求解CAD约束、应力或实际加工。','Ideal two-hole plate geometry and SVG projection; no CAD constraint solving, stress or manufacturing simulation.'],revolve:['完整轴套的理想几何投影；不含倒角、圆角、刀具或材料强度。','Ideal full-sleeve projection without fillets, chamfers, tooling or material strength.'],joint:['单转动副几何运动；不包含碰撞、摩擦、驱动力矩或接触。','Single-revolute-joint kinematics without collisions, friction, drive torque or contact.'],slice:['矩形体的教学分层与几何体积预算；不是完整切片器，不输出G-code或实际工时。','Rectangular layer teaching model and geometric volume budget; not a full slicer, with no G-code or real-time prediction.'],layout:['本地文章/海报排版练习；不连接秀米、Canva、公众号或真实报名系统。','Local article/poster layout practice; no connection to Xiumi, Canva, WeChat or real registration services.']};
